UPDATE content SET overview_uk = v.overview_uk, has_uk_translation = true FROM (VALUES
  (2951, 'Люблячий батько знаходить костюм клоуна для дня народження сина, але виявляє, що костюм є частиною злого прокляття, яке перетворює свого носія на вбивцю.'),
  (7038, 'Майкл Кайл — люблячий чоловік та сучасний глава родини, який керує домогосподарством із унікальним та своєрідним стилем виховання. Навчаючи своїх трьох дітей деяких життєвих уроків, він робить це з притаманним лише йому гумором.'),
  (6721, 'Улюблений усіма детектив-дог повертається, щоб шукати підказки — разом зі своїм енергійним племінником та четвірьма друзями-людьми.'),
  (5177, 'Коли улюбленого пса юного Віктора — Спаркі (який знімається в домашніх фільмах Віктора про монстрів) — збиває автомобіль, Віктор вирішує повернути його до життя єдиним відомим йому способом. Але коли «монстр» із болтами на шиї сіє хаос та жах у серцях сусідів Віктора, хлопцю доведеться переконати їх (і своїх батьків), що попри свій зовнішній вигляд, Спаркі залишається тим самим добрим та вірним другом, яким був завжди.'),
  (2686, 'Майлз Монро, кларнетист та власник магазину здорового харчування, виведений із кріостазу через 200 років у майбутньому світі, щоб допомогти повстанцям боротися з деспотичним урядовим режимом.'),
  (4300, 'Минуло тринадцять років відтоді, як Андроїди розпочали свою криваву бійню, і Сон Ґохан — єдиний, хто дає їм відсіч. Він бере сина Бульми, Транкса, собі в учні і навіть жертвує власним життям, щоб врятувати Транкса. Тепер Транкс мусить знайти спосіб змінити це апокаліптичне майбутнє.'),
  (6431, 'Ця пригодницька комедія намальована у простому стилі та поєднує милих лісових тваринок із екстремальним графічним насильством. Кожен епізод обертається навколо персонажів, які потрапляють у випадкові ситуації з кровопролиттям, болем, розчленуванням та/або смертю.'),
  (6677, 'Серіал охоплює період з 1944 по 2002 рік і слідкує за долями трьох родин: Кроуфордів, які намагаються приховати крах у Розвеллі та існування прибульців; Кізів, які стають об''єктами постійних експериментів прибульців; та Кларків, які надали притулок одному з інопланетян, що вижили після катастрофи.'),
  (4371, 'Отримавши завдання зловити Мукаде — зниклого ніндзя, Наруто Удзумакі вирушає до колись величних історичних руїн «Оуран», де переслідує та загонить у кут ніндзя-відступника. Мета Мукаде — сплячий лей-лайн у руїнах; він вивільняє силу лей-лайну, що спричиняє спалах світла, яке огортає Наруто та переносить його в минуле — на 20 років до початку серіалу. Коли Наруто прокидається, він зустрічає Четвертого Хокаґе — Мінато Намікадзе.'),
  (2345, 'Мисливець за трюфелями, який живе наодинці в дикій природі Орегону, мусить вирушити до Портленда, щоб знайти загадкову людину, яка викрала його улюблену пошукову свиню.'),
  (6484, 'За мотивами анімаційного серіалу «Час Пригод» ці чотири спецвипуски досліджують невідомі куточки світу — як із знайомими, так і з захопливими новими персонажами.'),
  (5931, 'Еміліано, заможний мексиканський бізнесмен, обдурений своїми друзями та партнерами. Переховуючись у Боготі, він отримує допомогу від Росаріо, співачки маріачі. Вона не знає про минуле Еміліано і про те, що його розшукує поліція двох країн та злочинна організація. Під новим ім''ям та особистістю він добре пристосовується до нового життя як учасник гурту маріачі та знаходить у Росаріо кохання всього свого життя. Але він боїться, що його таємниця розлучить їх. Йому потрібно очистити своє ім''я та вирішити свою справу, щоб уникнути цієї долі. Тим часом його кохання постійно зазнає випробувань від численних суперників, але Росаріо завжди вірить, що він був з нею чесним.'),
  (6877, 'Два космічних кораблі — один із доброзичливими Максималами, інший зі злими Предаконами — зазнають аварії на дольотовій планеті без гуманоїдів на шляху до Землі. Їхні екіпажі приймають форми місцевих тварин для захисту від надлишку природної енергії, перетворюючись на роботів для битви. Так розпочалися Звірині Війни...'),
  (6192, 'Група учнів школи Іст-Гай готується до прем''єри першої в історії школи постановки «Шкільний мюзикл». Розпалюються романи на знімальному майданчику, перевіряються на міцність старі дружби та зав''язуються нові, спалахує суперництво, а життя назавжди змінюється — адже ці молоді люди відкривають для себе перетворювальну силу, яку може дати лише шкільний драматичний гурток.'),
  (4993, 'Короткометражка від Pixar про коробку знахідок та невидимого монстра, що ховається всередині.')
) AS v(id, overview_uk) WHERE content.id = v.id;
